 if(tab==='templates'){for(const [key,name,detail] of [['survival','Sinh tồn','Ăn uống, ca thời vụ, vệ sinh, ngủ'],['worker','Người đi làm','Khởi hành 07:00, ca chính thức, sinh hoạt'],['student','Học tập','Buổi học, tự học, sinh hoạt']]){const row=lineCard(b,name,detail+' · Thêm vào lịch hiện tại.');modalButton(row,'Thêm mẫu',()=>{if(!addTemplate(p,key)){toast('Không đủ chỗ trong lịch.');return;}save();plannerScreen('tasks');},'primary');}}
