function start(s,replace=false){weatherTransition.reset();lastThunderSlot=null;if(replace){if(saveConflict)return toast(saveFault);if(playing&&!save(true))return;const r=persistSave(storage,SAVE_KEY,s,validate,{expected:expectedRaw,checkpoint:true});if(!r.ok){saveFault='Không thể thay thế bản lưu an toàn. Hãy xuất JSON và kiểm tra bộ nhớ.';renderNotice();toast(saveFault);return;}expectedRaw=r.raw;}endingRenderKey='';show('endingOverlay',false);for(const id of ['hud','left','right','bottom','world','labels','modal'])$(id).inert=false;npcReplanAt=0;npcPresentation.reset();transit=null;trafficState=null;renderer.transitSample=null;state=s;suspendLoadedPlan(state);autoRun=null;autoNext=0;notifications.clear();alertTransitions.clear();lastImportant=importantEntries(state);updateNotificationBadge();motion=newMotion();motion.yaw=activeVehicle(s)?.yaw??(s.riding?s.transport.bikeYaw:0);motion.targetYaw=motion.yaw;resetDriving(drive);resetInput();routeTarget=null;journey.clear();movementClock.reset(s.pos);displayPos={...s.pos};framePacer.reset();npcProximity.clear();playing=true;paused=false;path=[];destination=null;simSeconds=0;simSpeed=1;$('speed').value=1;renderer.camera={x:s.pos.x,z:s.pos.z,yaw:38,zoom:innerWidth<650?1.75:1.28,pitch:DEFAULT_PITCH};cameraRig.reset(renderer.camera);renderedView=null;setFocusView(true);syncCameraUI();show('start',false);for(const id of ['hud','left','right','bottom'])show(id,true);closeModal();updateUI();const stored=save();if(stored)toast('Chạm địa điểm hoặc dùng WASD để di chuyển.');return stored;}
