function masterBrowser(){
 const b=modal('Master Data','Danh mục chỉ đọc · dữ liệu mở rộng chưa kích hoạt gameplay.');
 b.append(node('p','',`${stats.catalogs} danh mục · ${stats.records} bản ghi · Schema ${MASTER_VERSION}`));
 const label=node('label','','Danh mục');label.htmlFor='masterCatalog';const select=node('select');select.id='masterCatalog';
 for(const [name,rows] of Object.entries(catalogs)){const o=node('option','',`${name} (${rows.length})`);o.value=name;select.append(o)}
 const filter=node('input');filter.type='text';filter.placeholder='Tìm tên hoặc ID';filter.setAttribute('aria-label','Tìm bản ghi');
 const results=node('div','master-results');
 function render(){const rows=catalogs[select.value],q=filter.value.trim().toLocaleLowerCase('vi');const found=rows.filter(r=>`${r.id} ${r.name}`.toLocaleLowerCase('vi').includes(q));results.replaceChildren(node('p','muted',`${found.length}/${rows.length} bản ghi`));for(const row of found){const item=node('details','master-record');item.append(node('summary','',`${row.name} · ${row.id}`),node('pre','',JSON.stringify(row,null,2)));results.append(item)}}
 select.onchange=()=>{filter.value='';render()};filter.oninput=render;b.append(label,select,filter,results);render();modalButton(b,'Quay lại cài đặt',settings,'close');
}
$('settings').onclick=settings;$('startSettings').onclick=settings;$('save').onclick=()=>save(true);
function cancelRoute(keepJourney=false){if(!keepJourney)journey.clear();transit=null;trafficState=null;renderer.transitSample=null;path=[];destination=null;routeTarget=null;replanned=false;}
function goPos(x,z,place=null,keepJourney=false){if(!playing||paused||modalOpen||saveConflict||graphicsLost||incarcerated(state)||ended(state))return;cancelRoute(keepJourney);brakeTouch=false;const route=(driving(state)?roadRoute:sidewalkRoute)(state.pos,{x,z});if(!route){journey.clear();toast('Không tìm thấy đường đi.');updateUI();return;}path=route.path;routeTarget=route.target;destination=place;replanned=false;if(!path.length)arrive();updateUI();}
function journeyTo(p,vehicle=null){journey.begin(p.id,vehicle?.id);if(vehicle){goPos(vehicle.pos.x,vehicle.pos.z,'pickup:'+vehicle.id,true);}else goPos(...p.door,p.id,true);}
function boardJourney(id){const v=parkedVehicles(state).find(v=>v.id===id);if(!v||!mountVehicle(state,id)){cancelRoute();toast('Không thể lên xe. Hãy chọn lại điểm đến.');return false;}motion.yaw=motion.targetYaw=v.yaw;movementClock.reset(state.pos);displayPos={...state.pos};const p=places.find(p=>p.id===journey.final);cancelRoute(true);if(p){if(!journey.boarded(id)){journey.stage='travel';journey.vehicle=id;}goPos(...p.door,p.id,true);}else journey.clear();save();return true;}
function pickupVehicle(v){const p=places.find(p=>p.id===(journey.final||destination));if(p){journey.begin(p.id,v.id);goPos(v.pos.x,v.pos.z,'pickup:'+v.id,true);}else goPos(v.pos.x,v.pos.z);}
const travelClock=m=>{const t=Math.floor(m%1440);return `${String(Math.floor(t/60)).padStart(2,'0')}:${String(t%60).padStart(2,'0')}`;};
function publicDetail(q){const mode=q.kind==='bus'?q.lines.join(' → ')+' · '+q.boards+' lượt vé':'Đón tận vị trí hiện tại';const wait=q.legs.filter(l=>l.kind==='wait'||l.kind==='taxi-wait').reduce((v,l)=>v+l.end-l.start,0);return `${mode} · ${Math.ceil(q.minutes)} phút · ${Math.round(q.distance)} m · chờ ${Math.ceil(wait)} phút · ${money(q.fare)}`;}
function startPublic(p,kind,quoteOverride=null,onPaid=null){if(transit||driving(state))return toast('Hãy xuống xe hoặc kết thúc chuyến hiện tại.');const q=quoteOverride||publicJourney(state,kind,p.id,state.minutes+simSeconds);if(!q||!payTransit(state,q,kind))return toast('Không đủ tiền hoặc không có chuyến phù hợp.');onPaid?.(q.fare);closeModal();cancelRoute();paused=false;journey.begin(p.id);journey.stage='public';destination=p.id;transit={kind,quote:q,speed:0,sample:sampleJourney(q,state.minutes+simSeconds)};path=transit.sample.path.map(v=>({...v}));routeTarget=q.target;save();updateUI();return true;}
function publicOptions(b,p){for(const kind of ['bus','taxi']){const q=publicJourney(state,kind,p.id,state.minutes+simSeconds);if(!q){if(kind==='bus')lineCard(b,'Xe buýt','Không có chuyến phù hợp trong thời gian chờ tối đa 90 phút.');continue;}const row=lineCard(b,kind==='bus'?'Xe buýt':'Taxi',publicDetail(q));if(kind==='bus'){const stops=q.legs.filter(l=>l.kind==='bus');const detail=node('details','finance-short');detail.append(node('summary','','Chi tiết tuyến và giờ khởi hành'));for(const leg of stops)detail.append(node('p','muted',`${leg.line} · ${travelClock(leg.start)} ${places.find(p=>p.id===leg.from).name} → ${travelClock(leg.end)} ${places.find(p=>p.id===leg.to).name}`));row.firstChild.append(detail);}modalButton(row,kind==='bus'?'Đi xe buýt':'Gọi taxi',()=>startPublic(p,kind),'primary',state.cash<q.fare);}}
function goPlace(p){if(!playing||paused||modalOpen||saveConflict||graphicsLost||incarcerated(state)||ended(state))return;if(transit)return toast('Hãy kết thúc hoặc hủy chuyến hiện tại trước.');const target={x:p.door[0],z:p.door[1]};if(distance(state.pos,target)<=2.5){cancelRoute();if(driving(state))parkVehicle(state,wrapYaw(motion.yaw));openPlace(p);return;}if(!driving(state)){const b=survivalModal('Đến '+p.name,'So sánh thời gian, chi phí và phương thức. Vé xe buýt/taxi thanh toán một lần khi xác nhận; hủy không hoàn tiền.');const w=sidewalkRoute(state.pos,target);if(w){const row=lineCard(b,'Đi bộ',`${Math.ceil(routeLength(state.pos,w.path)/config.walkSpeed*config.realSecondsPerMinute)} phút dự kiến ở 1× · miễn phí`);modalButton(row,'Đi bộ',()=>{closeModal();journeyTo(p)},'secondary');}const vehicles=journeyVehicles(state,parkedVehicles(state),sidewalkRoute,roadRoute,target);for(const v of vehicles){const a=sidewalkRoute(state.pos,v.pos),r=roadRoute(v.pos,target),model=record(v.id),len=routeLength(v.pos,r.path),fuel=(model.consumption||0)*len,minutes=(routeLength(state.pos,a.path)/config.walkSpeed+len/model.speed/0.85)*config.realSecondsPerMinute;const row=lineCard(b,'Lấy '+model.name,`${Math.ceil(minutes)} phút dự kiến · ${Math.round(len)} m đi xe${fuel?' · '+fuel.toFixed(2)+' '+(model.energyType==='electric'?'kWh':'lít'):''}`);modalButton(row,'Lấy '+model.name,()=>{closeModal();journeyTo(p,v)},'primary',v.id!=='VEH_BIKE'&&v.fuel+1e-8<fuel);}publicOptions(b,p);modalButton(b,'Hủy',closeModal,'close');return;}journeyTo(p);}

function arrive(){drive.speed=0;if(destination?.startsWith('pickup:')){boardJourney(destination.slice(7));return;}const parking=destination?.startsWith('parking:');if(parking){const slot=routeTarget;if(driving(state)&&slot&&!availableParking(state,driveId()).some(v=>distance(v.target,slot)<.05)){const next=availableParking(state,driveId()).find(v=>roadRoute(state.pos,v.target));if(next){goPos(next.target.x,next.target.z,'parking:'+next.id);return;}cancelRoute();toast('Không còn chỗ đỗ trống. Hãy chọn vị trí khác.');return;}cancelRoute();if(driving(state)){parkVehicle(state,0);motion.yaw=0;motion.targetYaw=0;if(['follow','close'].includes(cameraRig.mode))cameraRig.basePitch=Math.max(cameraRig.basePitch,60);commitActivity();toast('Đã đỗ xe tại bãi.');}return;}const npcId=destination?.startsWith('npc:')?destination.slice(4):null;const p=places.find(p=>p.id===destination);cancelRoute();if(npcId){if(nearNPC(state,npcId)){save();socialScreen('profile',npcId);}else{toast('NPC đang di chuyển, cập nhật vị trí.');goPos(npcAt(npcId,state.minutes,state).pos.x,npcAt(npcId,state.minutes,state).pos.z,'npc:'+npcId);}return;}if(p&&driving(state))parkVehicle(state,wrapYaw(motion.yaw));if(p&&distance(state.pos,{x:p.door[0],z:p.door[1]})<=2.5){if(autoRun&&state.planner.enabled&&autoRun.action.place===p.id){autoRun.stage='ready';save();return;}save();openPlace(p)}else{toast('Đã đến điểm đích.');save()}}
function survivalModal(title,desc){const b=modal(title,desc);b.classList.add('survival-dialog');const header=node('div','survival-header');header.append(...Array.from(b.children).slice(0,2));const close=node('button','survival-close','×');close.setAttribute('aria-label','Đóng cửa sổ');close.onclick=closeModal;header.append(close);b.prepend(header);if(roomReturn){const row=node('div','room-return');modalButton(row,'← Trở lại nội thất',roomReturn,'secondary');b.insertBefore(row,header.nextSibling);}return b}
