function survivalHelp(){const b=survivalModal('Sinh tồn & phục hồi',`${housingStatus(state)} · ${povertyStatus(state)} · ${money(state.cash)} tiền mặt.`);b.append(node('p','', 'Không đủ tiền gia hạn sẽ mất quyền sử dụng nhà thuê. Tài sản và tiền còn lại không bị xóa. Hãy dùng các hoạt động hỗ trợ để phục hồi và tìm việc trở lại.'));const income=actionCash(state,activities.shop.find(a=>a.id==='work'))+actionCash(state,activities.cafe.find(a=>a.id==='cafe_shift')),cost=-actionCash(state,activities.shop.find(a=>a.id==='meal'))*3-actionCash(state,activities.room.find(a=>a.id==='rent'));lineCard(b,'Dự toán sinh tồn · '+difficultyOf(state).name,`2 ca (6 giờ): ${money(income)} · 3 suất ăn + phòng: ${money(cost)} · Còn ${money(income-cost)}/ngày. Chưa tính chi phí khác; cần đủ sức và giờ phục vụ.`);lineCard(b,'Vườn cộng đồng','Đi bộ, uống nước và nghỉ ngơi miễn phí.');modalButton(b,'Đến vườn cộng đồng',()=>jumpPlace('community_garden'));modalButton(b,'Đến cửa hàng tiện lợi mới',()=>jumpPlace('mini_mart'));lineCard(b,'Công viên','Nước uống, rửa mặt, nghỉ tạm, suất ăn hỗ trợ khi đủ điều kiện.');modalButton(b,'Đến công viên',()=>jumpPlace('park'));lineCard(b,'Phòng khám','Khám hỗ trợ miễn phí một lần/ngày khi sức khỏe nguy kịch và thiếu tiền.');modalButton(b,'Đến phòng khám',()=>jumpPlace('clinic'));lineCard(b,'Công việc thời vụ','5 loại ca làm; tối đa 8 giờ/ngày. Cần đủ sức khỏe, năng lượng, độ no và nước uống.');for(const [id,label] of [['shop','Cửa hàng tiện lợi'],['cafe','Quán cà phê'],['market','Siêu thị'],['warehouse','Kho logistics'],['farm','Nông trại']])modalButton(b,label,()=>jumpPlace(id));modalButton(b,'Đóng',closeModal,'close')}
