 if(!familyHousingOK(state)&&familySize(state)>1)b.append(node('p','finance-notice','Nơi ở không đủ sức chứa hoặc đã mất chỗ ở. Hạnh phúc giảm mỗi ngày.'));if(p){lineCard(b,partnerName(state),relationshipLabel(state)+' · Tình cảm '+p.affection+'/100');modalButton(b,'Hồ sơ tình cảm',()=>familyScreen('love',p.id),'primary');modalButton(b,'Đi gặp '+record(p.id).name,()=>findNPC(p.id),'secondary',!!transit);}else{b.append(node('p','muted','Bạn có thể sống độc thân hoặc bắt đầu tìm hiểu một người đã quen.'));modalButton(b,'Tìm hiểu NPC',()=>familyScreen('love'),'primary')}
 if(p?.stage==='married')for(const a of familyActions.filter(x=>['time','child','reconcile'].includes(x.id)))action(b,a,p.id);
 if(f.pending)lineCard(b,'Đang chuẩn bị đón con',`Còn ${Math.ceil((f.pending.due-state.minutes)/1440)} ngày`);for(const c of f.children)lineCard(b,c.name,`${childAge(state,c)} tuổi · Sức khỏe ${c.health}/100 · Chăm sóc ${c.care}/100`);
