 for(const c of f.children){const age=childAge(state,c),r=childReason(state,c.id);meter(lineCard(b,c.name,`${age} tuổi · Chăm sóc ${c.care}/100 · Sức khỏe ${c.health}/100 · Cha/mẹ còn lại: ${record(c.parent).fullName}`),c.care);const field=node('input');field.value=c.name;field.maxLength=24;field.setAttribute('aria-label','Tên '+c.name);const row=node('div','fin-actions');row.append(field);modalButton(row,'Lưu tên',()=>run(()=>renameChild(state,c.id,field.value),()=>familyScreen('children')));b.append(row);if(age<18){if(r)b.append(node('p','muted',r));modalButton(b,'Chăm sóc '+c.name+' · 45 phút',()=>run(()=>careChild(state,c.id),()=>familyScreen('children'),'Đã chăm sóc con'),'primary',!!r||!!transit)}}modalButton(b,'Đến công viên hỗ trợ',()=>jumpPlace('park'),'secondary',!!transit);modalButton(b,'Về nhà',()=>jumpPlace(currentHomePlace(state)),'secondary',!currentHomePlace(state)||!!transit);
