 if(tab==='history'){b.append(node('p','muted','Hồ sơ đã xử lý được lưu lâu dài; kết quả không đủ căn cứ không phải án tích.'));if(!l.cases.some(c=>c.verdict!=='pending'))b.append(node('p','finance-notice','Chưa có phán quyết.'));for(const c of l.cases.filter(c=>c.verdict!=='pending')){const r=section(label(c),c.verdict==='cleared'?'Không đủ căn cứ xử phạt':'Phán quyết có vi phạm');lineCard(r,'Ngày phán quyết',transactionDate(c.verdictAt));if(c.verdict==='guilty'){const p=record(record(c.offense).penalty);lineCard(r,'Mức phạt đã tuyên',money(p.fine));lineCard(r,'Án tù đã tuyên',c.prisonMonths+' tháng');lineCard(r,'Tình trạng',phaseName(c));}}}
