function renderLifeSummary(b,e){const r=record(e.id);b.append(node('div','eyebrow',r.group.toUpperCase()+' · THẾ HỆ '+e.generation),node('h2','',r.name),node('p','muted',e.name+' · '+e.age+' tuổi · '+transactionDate(e.at)));lineCard(b,'Độ khó',difficultyOf(e).name+(e.difficulty===undefined?' (bản lưu cũ)':''));lineCard(b,'Lý do tổng kết',({age:'Kết thúc vòng đời ở tuổi 100',health:'Sức khỏe suy kiệt kéo dài',reflection:'Chủ động tổng kết tuổi già'})[e.cause]);const grid=node('div','aging-metrics');for(const [label,value] of [['Điểm cuộc đời',e.score+'/100'],['Tài sản ròng',money(e.net)],['Tổng tài sản',money(e.assets)],['Nghĩa vụ còn lại',money(e.debt)],['Di sản khả dụng',money(e.estate)],['Ca làm đã hoàn thành',String(e.shifts)],['Con cái / bạn bè',e.children+' / '+e.friends],['Phán quyết vi phạm',String(e.convictions)],['Lương hưu đã nhận',money(e.pensionReceived)]])lineCard(grid,label,value);b.append(grid);lineCard(b,'Sức khỏe / hạnh phúc',e.health+' / '+e.happy);lineCard(b,'Đạo đức / uy tín',e.ethics+' / '+e.reputation);lineCard(b,'Hạnh phúc gia đình',e.family+'/100');b.append(node('h3','','Thành tựu'));if(!e.achievements.length)b.append(node('p','muted','Chưa có thành tựu được ghi nhận.'));for(const id of e.achievements)lineCard(b,record(id).name,record(id).description);}
function hallScreen(s=playing?state:readSave(storage)){const b=survivalModal('Hall of Fame','Các hành trình đã kết thúc được lưu cùng bản save, tối đa 20 hồ sơ trước đó.');const entries=s?[...(s.aging.ending?[s.aging.ending]:[]),...s.aging.archive]:[];if(!entries.length)b.append(node('p','muted','Chưa có cuộc đời hoàn thành.'));for(const e of entries){const row=lineCard(b,e.name+' · '+record(e.id).name,'Thế hệ '+e.generation+' · '+e.age+' tuổi · '+money(e.net)+' · Điểm '+e.score);modalButton(row,'Chi tiết',()=>{const d=survivalModal('Báo cáo cuộc đời',record(e.id).conditionDescription);renderLifeSummary(d,e);modalButton(d,'Quay lại Hall of Fame',()=>hallScreen(s),'close');});}modalButton(b,'Đóng',closeModal,'close');}
function agingScreen(tab='overview'){if(ended(state)||incarcerated(state))return;if(transit)return toast('Hãy kết thúc chuyến đi trước.');if(driving(state))parkVehicle(state,wrapYaw(motion.yaw));captureMilestones(state);const a=state.aging,b=survivalModal('Vòng đời & di sản',state.name+' · '+ageOf(state)+' tuổi · '+lifeStage(state).name);b.classList.add('finance-dialog');const tabs=node('div','edu-tabs aging-tabs');for(const [id,label] of [['overview','Vòng đời'],['retire','Hưu trí'],['legacy','Di sản'],['endings','Kết cục']])modalButton(tabs,label,()=>agingScreen(id),id===tab?'primary':'secondary');b.append(tabs);if(tab==='overview'){const stage=node('div','aging-stages');for(const r of catalogs.Life_Stages){const x=node('div',r.id===lifeStage(state).id?'stage-current':'');x.append(node('strong','',r.name),node('small','',r.minAge+'–'+r.maxAge+' tuổi'));stage.append(x);}b.append(stage);lineCard(b,'Tuổi hiện tại',ageOf(state)+' / 100 tuổi');lineCard(b,'Ảnh hưởng tuổi tác','−'+agePenalty(state)+' điểm hiệu suất');lineCard(b,'Sức khỏe nguy kịch liên tục (từ 75 tuổi)',a.criticalDays+'/30 ngày');lineCard(b,'Tài sản ròng cao nhất đã ghi nhận',money(a.peakNet));lineCard(b,'Thế hệ',String(a.generation));b.append(node('h3','','Thành tựu'));for(const r of catalogs.Achievements)lineCard(b,(a.achievements.includes(r.id)?'✓ ':'○ ')+r.name,r.description);modalButton(b,'Hall of Fame',()=>hallScreen(state));}else if(tab==='retire'){lineCard(b,'Tình trạng',retired(state)?'Đã nghỉ hưu từ '+transactionDate(a.retiredAt):'Chưa nghỉ hưu');lineCard(b,'Ca làm chính thức',String(formalShifts(state)));lineCard(b,'Lương hưu mỗi 30 ngày',money(retired(state)?a.pension:pensionQuote(state)));lineCard(b,'Tổng lương hưu đã nhận',money(a.pensionReceived));if(retired(state))lineCard(b,'Kỳ tiếp theo',transactionDate(a.pensionDue));else{b.append(node('p','muted','Từ 60 tuổi, có thể kết thúc hợp đồng chính thức để nghỉ hưu. Cần ít nhất 240 ca chính thức để nhận lương hưu; nghỉ hưu không thể đảo ngược. Kinh doanh, đầu tư và sinh hoạt vẫn khả dụng.'));const why=retirementReason(state);if(why)b.append(node('p','action-reason',why));modalButton(b,'Xác nhận nghỉ hưu',()=>{if(confirm('Nghỉ hưu vĩnh viễn? Hợp đồng hiện tại được kết thúc và thanh toán lương đã tích lũy.')){if(retire(state)){commitActivity();agingScreen('retire');}else toast('Không thể nghỉ hưu.');}},'primary',!!why);}}else if(tab==='legacy'){const e=estatePreview(state);lineCard(b,'Giá trị thu hồi ước tính',money(e.gross));lineCard(b,'Nghĩa vụ phải khấu trừ',money(e.debt));lineCard(b,'Di sản có thể chuyển giao',money(e.estate));for(const c of state.family.children)lineCard(b,c.name,childAge(state,c)+' tuổi · '+(childAge(state,c)>=18?'Đủ điều kiện kế thừa':'Chưa đủ tuổi'));b.append(node('p','finance-notice','Khi kết thúc, có thể chọn một người con trưởng thành nhận toàn bộ phần di sản ròng bằng tiền. Thế hệ mới bắt đầu ở 18 tuổi trong timeline mới; tài sản hiện vật, nợ và NPC không chuyển sang. Không có người thừa kế thì kết thúc lượt chơi.'));}else{const matches=endingCandidates(state);lineCard(b,'Kết cục dự kiến',record(matches[0].id).name);b.append(node('p','muted','Kết quả có thể thay đổi theo cuộc đời. Mỗi lượt chỉ chọn một kết cục chính theo thứ tự ưu tiên.'));for(const g of ['success','ordinary','failure','legal']){b.append(node('h3','',({success:'Thành công',ordinary:'Bình dị',failure:'Khó khăn',legal:'Trách nhiệm & phục hồi'})[g]));for(const r of catalogs.Life_Endings.filter(x=>x.group===g))lineCard(b,(matches.some(x=>x.id===r.id)?'✓ ':'○ ')+r.name,r.conditionDescription+(r.id==='END_LEGAL_04'?' · Chưa có nghề công chức tương ứng':''));}modalButton(b,'Tổng kết cuộc đời (từ 70 tuổi)',()=>{if(confirm('Kết thúc lượt chơi này? Không thể tiếp tục cuộc đời hiện tại sau khi xác nhận.')){if(endLife(state,'reflection')){commitActivity();}else toast('Chưa đủ điều kiện tổng kết.');}},'primary',ageOf(state)<70||pendingCustody(state).length>0);}modalButton(b,'Đóng',closeModal,'close');}
let endingRenderKey='';
function syncEndingUI(){if(!playing||!ended(state))return false;if(state.planner.enabled)stopPlanner('Cuộc đời đã kết thúc.');const e=state.aging.ending;const key=e.name+':'+e.at+':'+e.id;if(endingRenderKey===key)return true;show('endingOverlay',true);show('custodyOverlay',false);for(const id of ['hud','left','right','bottom','world','labels','modal'])$(id).inert=true;resetInput();cancelRoute();transit=null;closeModal();paused=true;endingRenderKey=key;const b=$('endingBody');b.replaceChildren(node('div','eyebrow','FROM ZERO · HÀNH TRÌNH HOÀN THÀNH'));renderLifeSummary(b,e);b.append(node('h3','','Chương tiếp theo'));for(const h of e.heirs)modalButton(b,'Kế thừa: '+h.name+' · '+money(e.estate),()=>{if(confirm('Bắt đầu thế hệ mới, chuyển di sản cho '+h.name+'? Hành trình hiện tại sẽ được lưu trong Hall of Fame.')){const next=nextLife(state,fresh(h.name,state.difficulty),h.id);if(next)start(next,true);}},'primary');modalButton(b,'Bắt đầu cuộc đời mới độc lập',()=>{if(confirm('Bắt đầu cuộc đời mới với vốn theo độ khó hiện tại, không nhận di sản?'))start(nextLife(state,fresh('Minh',state.difficulty)),true);});modalButton(b,'Xuất bản lưu kết thúc',()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(state)],{type:'application/json'}));const a=node('a');a.href=url;a.download='FromZero-completed-life.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});modalButton(b,'Về màn hình chính',titleMenu);save();return true;}
$('agingOpen').onclick=()=>agingScreen();$('hallOpen').onclick=()=>hallScreen();

renderer.camera={x:SIZE/2,z:SIZE/2,yaw:38,zoom:.46,pitch:DEFAULT_PITCH};cameraRig.reset(renderer.camera,'overview');setFocusView(false);syncCameraUI();requestAnimationFrame(frame);pwa=setupPWA({onChange:renderNotice,onControllerChange:()=>{if(!playing||save(true))location.reload();else renderNotice();}});renderNotice();

$('mobileMenu').onclick=gameMenu;

function guideScreen(){
 const b=survivalModal('Hướng dẫn cuộc đời','From Zero V2.9.0 · Không có một con đường duy nhất. Bạn tự quyết định mục tiêu.');b.classList.add('guide-dialog');
 const canTravel=playing&&!ended(state)&&!incarcerated(state)&&!saveConflict&&!graphicsLost;
 const preview=playing?state:fresh();
 const steps=guideSteps(preview),done=steps.filter(x=>x.done).length;
 const intro=node('div','guide-intro');intro.append(node('strong','',canTravel?`Mục tiêu khởi đầu · ${done}/${steps.length}`:'5 mục tiêu gợi ý khi mới đến An Lạc'),node('p','muted','Mục tiêu chỉ để tham khảo, không cấp thêm tiền hay XP. Ăn uống và uống nước được đánh giá theo ngày; tài sản theo trạng thái hiện tại.'));b.append(intro);
 for(const step of steps){const row=lineCard(b,(canTravel&&step.done?'✓ ':'○ ')+step.title,step.detail);if(canTravel){modalButton(row,'Đến nơi',()=>jumpPlace(step.place),'secondary',!!transit);if(step.id==='meal')modalButton(row,'Đến cửa hàng',()=>jumpPlace('shop'),'secondary',!!transit);}}
 b.append(node('h3','','Điều khiển'),node('p','muted','PC: WASD / phím mũi tên, Shift chạy, E tương tác, Esc hủy đường hoặc đóng cửa sổ; F theo nhân vật, C cận cảnh, Z/X xoay, Q/R nghiêng, V ẩn HUD phụ. Mobile: joystick, nút CHẠY, chạm địa điểm, hai ngón zoom/xoay; chọn góc nhìn tại thanh camera. Có thể tạm dừng hoặc giảm tốc độ thời gian.'));
 b.append(node('h3','','Bảo vệ tiến trình'),node('p','muted','Game lưu trên thiết bị, không có đồng bộ cloud. Cài đặt → Xuất bản lưu JSON để sao lưu trước khi đổi thiết bị hoặc cập nhật. Chỉ chơi một tab. Không xóa dữ liệu trình duyệt nếu chưa xuất save.'));
 if(canTravel)modalButton(b,'Xem dự toán sinh tồn',survivalHelp,'secondary');modalButton(b,canTravel?'Tiếp tục cuộc đời':'Đóng',closeModal,'primary');
}
$('startGuide').onclick=guideScreen;$('guideOpen').onclick=guideScreen;

// HUD 2.0: reuse existing screens rather than duplicating their business rules.
function appendPlan(b){const row=node('div','day-plan');for(const [offset,label] of [[0,'Hôm nay'],[1,'Ngày mai']]){const p=dayPlan(state,offset),card=node('div','plan-card');card.append(node('small','muted',label),node('strong','',p.weekday+' · '+p.date),node('span',p.working?'plan-work':'muted',p.label));if(offset===0&&p.working)card.append(node('small','muted',shiftStatus(state)));row.append(card);}b.append(row);}
function gameMenu(){if(!playing||saveConflict||graphicsLost||ended(state)||incarcerated(state))return;const b=survivalModal('Menu cuộc đời','Chọn một hệ thống để quản lý. Gameplay tạm dừng khi mở cửa sổ.');b.classList.add('hud-dialog');const quick=node('div','hud-menu-grid');modalButton(quick,'Kế hoạch & tự động hóa',()=>plannerScreen(),'primary');modalButton(quick,'Hồ sơ nhân vật',characterPanel,'secondary');modalButton(quick,'Thông báo ('+notifications.unread+')',notificationCenter,'secondary');b.append(quick);for(const [title,ids] of [['Cuộc sống',['guideOpen','avatarOpen','inventoryOpen','routineOpen','survivalOpen','healthOpen','housingOpen','transportOpen']],['Phát triển',['educationOpen','careerOpen','financeOpen','bankingOpen','businessOpen','economyOpen']],['Quan hệ & cuộc đời',['socialOpen','familyOpen','storyOpen','legalOpen','recoveryOpen','agingOpen']],['Thành phố',['mobilePlaces','openCityMap']]]){b.append(node('h3','',title));const grid=node('div','hud-menu-grid');for(const id of ids){const origin=$(id);modalButton(grid,origin.textContent.trim(),()=>{closeModal();origin.click()},'secondary',origin.disabled);}b.append(grid);}modalButton(b,'Cài đặt',settings);}
function characterPanel(){const b=survivalModal('Hồ sơ nhân vật',state.name+' · '+calendar(state).age+' tuổi · '+educationLevel(state).name);b.classList.add('hud-dialog');const head=node('div','character-summary');head.append(node('span','avatar',state.name.slice(0,2).toUpperCase()),node('div','',currentJob(state)?.name||'Chưa có việc chính thức'));b.append(head);appendPlan(b);const needs=node('div','character-needs');for(const [key,label,icon] of NEEDS){const item=node('div','character-need');const progress=node('progress');progress.max=100;progress.value=state[key];progress.className=needLevel(key,state[key]);progress.setAttribute('aria-label',label);item.append(node('span','',icon+' '+label+' · '+Math.round(state[key])),progress);needs.append(item);}b.append(needs);const assets=node('div','finance-summary');for(const [label,value] of [['Tiền mặt',money(state.cash)],['Tài khoản',money(state.personalFinance.account)],['Nhà ở',residence(state)?currentHome(state).name:housingStatus(state)],['Phương tiện',String(state.transport.vehicles.length+(state.bike?1:0))+' xe']]){const item=node('div');item.append(node('small','',label),node('strong','',value));assets.append(item);}b.append(assets);const buttons=node('div','hud-menu-grid');for(const [label,fn] of [['Ngoại hình',appearanceScreen],['Sức khỏe',healthScreen],['Sự nghiệp',careerScreen],['Tài chính',finance]])modalButton(buttons,label,()=>fn());b.append(buttons);}
function updateNotificationBadge(){const el=$('notificationCount');if(el){el.textContent=notifications.unread?String(notifications.unread):'';el.classList.toggle('hidden',!notifications.unread);}}
function notificationCenter(){notifications.read();updateNotificationBadge();const b=survivalModal('Thông báo','Chỉ sự kiện quan trọng và cảnh báo. Thao tác thường ngày không tạo thông báo.');b.classList.add('hud-dialog');const alerts=[...new Set([...warnings(state),...financialWarnings(state)])];b.append(node('h3','','Cần chú ý'));for(const v of alerts) b.append(node('p','notice-row',String(v)));if(!alerts.length)b.append(node('p','muted','Không có cảnh báo hiện tại.'));b.append(node('h3','','Thông báo phiên chơi'));for(const r of notifications.rows){const item=node('div','notice-row');item.append(node('small','muted',weekday({minutes:r.time})+' · '+dateLabel({minutes:r.time})),node('p','',r.message));b.append(item);}if(!notifications.rows.length)b.append(node('p','muted','Chưa có thông báo mới.'));b.append(node('h3','','Sự kiện quan trọng'));for(const r of importantEntries(state))b.append(node('p','notice-row',r));}
function pauseMenu(){if(!playing||saveConflict||graphicsLost||modalOpen||incarcerated(state)||ended(state))return;paused=true;resetInput();updateUI();const b=survivalModal('Tạm dừng','Đồng hồ mô phỏng đã dừng.');b.classList.add('hud-dialog');modalButton(b,'▶ Tiếp tục chơi',()=>{closeModal();paused=false;updateUI()},'primary');modalButton(b,'Lưu tiến trình',()=>save(true));modalButton(b,'Cài đặt',settings);modalButton(b,'Hướng dẫn',guideScreen);modalButton(b,'Về màn hình chính',()=>{if(confirm('Lưu và về màn hình chính?'))titleMenu()});}
function updateCompactNeeds(){for(const [key,label] of NEEDS){const el=$('compact-'+key);if(!el)continue;const value=Math.round(state[key]);el.querySelector('b').textContent=value;el.dataset.level=needLevel(key,value);el.setAttribute('aria-label',label+' '+value+'/100');el.querySelector('i').style.width=value+'%';}}
for(const [key,label,icon] of NEEDS){const item=node('button','compact-need');item.id='compact-'+key;item.title=label;const line=node('span');line.append(node('span','need-icon',icon),node('b','','100'));const bar=node('span','compact-track');bar.append(node('i'));item.append(line,bar);item.onclick=characterPanel;$('needsStrip').append(item);}
for(const [id,label,icon,fn] of [['profileQuick','Nhân vật','♙',characterPanel],['bagQuick','Túi đồ','▣',inventory],['planQuick','Lịch','▦',routine],['mapQuick','Bản đồ','⌖',cityMap],['noticeQuick','Thông báo','◉',notificationCenter],['menuQuick','Menu','☰',gameMenu]]){const btn=node('button','action-item');btn.id=id;btn.append(node('span','action-icon',icon),node('span','action-label',label));btn.onclick=()=>fn();if(id==='noticeQuick'){const count=node('b','notification-count hidden');count.id='notificationCount';btn.append(count);}$('actionBar').append(btn);}
$('cameraExpand').onclick=()=>{const expanded=$('cameraExpand').getAttribute('aria-expanded')!=='true';$('cameraExpand').setAttribute('aria-expanded',String(expanded));$('cameraExpand').closest('.camera-controls').classList.toggle('camera-expanded',expanded);};
// Keep the minimap and expanded panels below the actual dynamic HUD height (safe-area, wrapping, rotation).
function measureHud(){const strip=$('needsStrip');if(strip.getClientRects().length)document.documentElement.style.setProperty('--hud-strip-bottom',Math.ceil(strip.getBoundingClientRect().bottom)+'px');}
if(typeof ResizeObserver==='function'){const observer=new ResizeObserver(measureHud);observer.observe($('hud'));observer.observe($('needsStrip'));}window.addEventListener('resize',measureHud,{passive:true});
